// ================= revenue: what the CRO can do with the measured uplift =================
function gConsequences() {
  const s = scope(), reg = GREG.map((r) => { const g = gRegion(r); return [r, g.up, g.fc, g.up / g.fc]; }), mxr = Math.max.apply(null, reg.map((x) => x[1]));
  const rep = {}; GA.forEach((a) => { const q = (rep[a.rep] = rep[a.rep] || { up: 0, n: 0 }); q.up += a.uplift; q.n++; });
  const reps = Object.entries(rep).sort((x, y) => y[1].up - x[1].up), none = reps.filter((r) => r[1].up === 0), mxp = reps[0][1].up || 1;
  const drv = (a) => (a.thread === 'single' ? 'Executive engagement' : a.thread === 'business' ? 'Business case' : a.thread === 'stalled' ? 'Renewal recovery' : a.renewalDays <= 180 ? 'Renewal' : 'Expansion'), act = {}; GA.forEach((a) => (act[drv(a)] = (act[drv(a)] || 0) + a.uplift));
  const acts = Object.entries(act).sort((x, y) => y[1] - x[1]), mxa = acts[0][1] || 1, low = reg.slice().sort((x, y) => x[3] - y[3])[0];
  const bar = (n, v, mx, t) => '<div class="hbar"><span class="hn">' + esc(n) + '</span><div class="mini" style="height:10px"><i style="width:' + (v / mx) * 100 + '%;background:var(--gx-green)"></i></div><span class="hv num">' + t + '</span></div>';
  return '<div class="card"><div class="hd"><div><span class="kicker">Closing the loop</span><h3>What the CRO can do with the uplift</h3></div><span class="gx-chip o">Attribution is mock</span></div>' +
    '<div class="gx-outs"><div><span class="gx-on">01</span><b>Workflows live in weeks</b><small>Multiple workflows deployed and running across the team. Here: ' + GPLAYS.length + ' guided plays and a scoring workbench.</small></div><div><span class="gx-on">02</span><b>A forecast I can trust</b><small>Revenue that is measurable, tangible and realistic. Here: ' + fm(s.fc3, 1) + ' risk-adjusted against ' + fm(s.repfc3, 1) + ' from the sales team this quarter.</small></div><div><span class="gx-on">03</span><b>One shared context</b><small>The whole go-to-market team working from the same picture. Here: four feeds resolved to one company at ' + gDbkPct + '%.</small></div></div>' +
    '<div class="grid g3" style="margin-top:14px"><div><div class="gx-subh">Which regions gain most</div>' + reg.map((x) => bar(x[0], x[1], mxr, gfm(x[1], 1) + ' · ' + gpc(x[3]))).join('') + '</div><div><div class="gx-subh">Which sellers gain most</div>' + reps.slice(0, 4).map((r) => bar(r[0], r[1].up, mxp, gfm(r[1].up, 1))).join('') + '<p class="gx-pnote" style="margin-top:6px">' + none.length + ' of ' + reps.length + ' sellers have no uplift yet.</p></div><div><div class="gx-subh">Which activities pay most</div>' + acts.map((x) => bar(x[0], x[1], mxa, gfm(x[1], 1))).join('') + '</div></div>' +
    '<p class="note" style="margin-top:12px"><b>What the CRO does next:</b> re-enable where uplift is thinnest. ' + low[0] + ' returns ' + gpc(low[3]) + ' of its forecast, so it gets the next coaching and workflow effort, and the sellers with no uplift get a guided play first. The attribution of uplift to regions, sellers and activities is mock data here.</p></div>';
}

